import csv
import io
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    expected_width = 5

    try:
        parsed = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False))
    except csv.Error:
        parsed = []

    nonempty = [(index, row) for index, row in enumerate(parsed) if row and any(value.strip() for value in row)]
    if not nonempty:
        return {"columns": [], "rows": []}

    header_position = next(
        (index for index, row in nonempty if len(row) == expected_width),
        nonempty[0][0],
    )
    header = parsed[header_position]
    header = list(header)
    if header:
        header[0] = header[0].lstrip("\ufeff")

    columns = header[:expected_width]
    if len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))

    rows: List[List[str]] = []
    for row in parsed[header_position + 1:]:
        if not row or not any(value.strip() for value in row):
            continue
        values = list(row)
        if len(values) > expected_width:
            values = values[:expected_width - 1] + [",".join(values[expected_width - 1:])]
        elif len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        rows.append(values)

    return {"columns": columns, "rows": rows}
